{
  "tool": "TodoWrite",
  "description": "Use this tool to create and manage a structured task list for your current coding session.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "todos": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "description": "Unique identifier for the TODO item"
            },
            "content": {
              "type": "string",
              "description": "The description/content of the TODO item"
            },
            "status": {
              "type": "string",
              "enum": [
                "pending",
                "in_progress",
                "completed",
                "cancelled"
              ],
              "description": "The current status of the TODO item"
            }
          },
          "required": [
            "id",
            "content",
            "status"
          ]
        },
        "minItems": 2,
        "description": "Array of TODO items to update or create"
      },
      "merge": {
        "type": "boolean",
        "description": "Whether to merge the todos with the existing todos. If true, the todos will be merged into the existing todos based on the id field. You can leave unchanged properties undefined. If false, the new todos will replace the existing todos."
      }
    },
    "required": [
      "todos",
      "merge"
    ]
  }
}

{
  "tool": "issue_read",
  "description": "Get information about a specific issue in a GitHub repository.",
  "inputSchema": {
    "type": "object",
    "properties": {
      "issue_number": {
        "type": "number",
        "description": "The number of the issue"
      },
      "method": {
        "type": "string",
        "description": "The read operation to perform on a single issue.\nOptions are:\n1. get - Get issue details. Also returns best-effort hierarchy flags (`has_parent`, `has_children`); `parent` and `sub_issues_summary` are optional relationship summaries, and `closed_by_pull_requests` summarizes the pull requests configured to close the issue as `total_count` plus up to 5 `references`.\n2. get_comments - Get issue comments.\n3. get_sub_issues - Get sub-issues (children) of the issue.\n4. get_parent - Get the parent issue, if this issue is a sub-issue of another.\n5. get_labels - Get labels assigned to the issue.\n",
        "enum": [
          "get",
          "get_comments",
          "get_sub_issues",
          "get_parent",
          "get_labels"
        ]
      },
      "owner": {
        "type": "string",
        "description": "The owner of the repository",
        "x-mcp-header": "owner"
      },
      "page": {
        "type": "number",
        "description": "Page number for pagination (min 1)",
        "minimum": 1
      },
      "perPage": {
        "type": "number",
        "description": "Results per page for pagination (min 1, max 100)",
        "minimum": 1,
        "maximum": 100
      },
      "repo": {
        "type": "string",
        "description": "The name of the repository",
        "x-mcp-header": "repo"
      }
    },
    "required": [
      "method",
      "owner",
      "repo",
      "issue_number"
    ]
  }
}

