+function git(cwd, args) {
+  const result = spawnSync("git", ["-c", "commit.gpgsign=false", "-c", "user.name=Delta Bundle", "-c", "user.email=delta@tessera.local", ...args], {
+    cwd,
+    encoding: "utf8",
+    env: enabledEnv,
