+    commit(repo, { [`pages/base-${String(i).padStart(2, "0")}.md`]: page(`Base page ${i}`, 28, `Base visit ${i}.`) }, `base ${i}`);
+  }
+  const marks = { 0: git(repo, ["rev-parse", "HEAD"]) };
+  for (let n = 1; n <= 20; n += 1) {
+    const files = {};
+    for (let f = 0; f < 3; f += 1) {
+      const id = (n * 3 + f) % BASE_PAGES;
+      const path = `pages/base-${String(id).padStart(2, "0")}.md`;
+      files[path] = `${page(`Base page ${id}`, 28, `Base visit ${id}.`)}\n## Update ${n}.${f}\n\n${SENTENCES[n % SENTENCES.length]} The editor added this section after sync mark ${n}, file ${f}, so the delta names more than one path.\n`;
+    }
+    files[`notes/update-${String(n).padStart(2, "0")}.md`] = page(`Update note ${n}`, 6, `Note ${n} was written offline.`);
