+}
+
+function median(values) {
+  const sorted = [...values].sort((a, b) => a - b);
+  const mid = Math.floor(sorted.length / 2);
+  if (sorted.length % 2 === 0) return Math.round((sorted[mid - 1] + sorted[mid]) / 2);
+  return sorted[mid];
+}
+
+function timeFetch(repo, bundle, full) {
+  const start = process.hrtime.bigint();
+  fetchBundle({ repo, bundle, full, env: enabled });
+  return Number(process.hrtime.bigint() - start) / 1e6;
+}
+
+const sender = buildSender();
+const rows = [];
+for (const n of NS) {
+  const basis = sender.marks[20 - n];
+  const fullBytes = [];
+  const deltaBytes = [];
+  const fullMs = [];
+  const deltaMs = [];
+  for (let run = 0; run < RUNS; run += 1) {
+    const work = mkdtempSync(join(tmpdir(), "deltabundle-bench-out-"));
+    const fullOut = join(work, "full.bundle");
+    const deltaOut = join(work, "delta.bundle");
+    const full = createBundle({ repo: sender.repo, out: fullOut, full: true, env: enabled });
+    const delta = createBundle({ repo: sender.repo, out: deltaOut, peerRef: basis, env: enabled });
+    fullBytes.push(full.bytes);
+    deltaBytes.push(delta.bytes);
+    const fullRecv = cloneAt(sender.repo, basis);
+    const deltaRecv = cloneAt(sender.repo, basis);
+    fullMs.push(timeFetch(fullRecv, fullOut, true));
+    deltaMs.push(timeFetch(deltaRecv, deltaOut, false));
+  }
+  const fullB = median(fullBytes);
+  const deltaB = median(deltaBytes);
+  rows.push({
+    n,
+    commits: n,
+    fullBytes: fullB,
+    deltaBytes: deltaB,
+    byteRatio: Number((fullB / deltaB).toFixed(2)),
+    fullFetchMs: median(fullMs.map((v) => Math.round(v))),
+    deltaFetchMs: median(deltaMs.map((v) => Math.round(v))),
+  });
+}
+
+process.stdout.write(`${JSON.stringify({ runs: RUNS, basePages: BASE_PAGES, rows }, null, 2)}\n`);
+
+if (process.argv[1] && process.argv[1] !== fileURLToPath(import.meta.url)) {
+  // imported, do not run
+}

