        GIT_COMMITTER_NAME: "Delta Bench",
        GIT_COMMITTER_EMAIL: "bench@tessera.local",
      },
    },
  );
  if (result.status !== 0) throw new Error((result.stderr || result.stdout || "git failed").trim());
  return (result.stdout || "").trim();
}

