import { afterAll, describe, expect, it } from "vitest";
import express from "express";
import { createServer, type Server } from "node:http";
import {
  DbUnavailableError,
  db,
  getDb,
  getPool,
  isDbConfigured,
  setPoolFactoryForTests,
} from "@workspace/db";
import healthRouter from "../routes/health";
import inventionsRouter from "../routes/inventions";
import { rejectWhenDatabaseNotConfigured } from "../lib/db-availability";

const poolCalls: Array<{ connectionString?: string }> = [];

class FakePgPool {
  readonly connectionString: string | undefined;
  constructor(config: { connectionString?: string }) {
    this.connectionString = config.connectionString;
    poolCalls.push(config);
  }
  on(): this {
    return this;
  }
  query(): Promise<{ rows: unknown[]; rowCount: number }> {
    return Promise.resolve({ rows: [], rowCount: 0 });
  }
  connect(): Promise<{ query: () => Promise<{ rows: unknown[]; rowCount: number }>; release: () => void }> {
    return Promise.resolve({
      query: () => Promise.resolve({ rows: [], rowCount: 0 }),
      release: () => undefined,
    });
  }
  end(): Promise<void> {
    return Promise.resolve();
  }
}

const FAKE_CONNECTION_STRING = "postgres://configured-path-test@db.invalid/none";

async function listen(app: express.Express): Promise<{ server: Server; baseUrl: string }> {
  const server = createServer(app);
  await new Promise<void>((resolve) => {
    server.listen(0, "127.0.0.1", () => resolve());
  });
  const address = server.address();
  if (!address || typeof address === "string") throw new Error("no test server address");
  return { server, baseUrl: `http://127.0.0.1:${address.port}` };
}

describe("optional database boot", () => {
  const servers: Server[] = [];

  afterAll(async () => {
    await Promise.all(servers.map((server) => new Promise<void>((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    })));
  });

  it("imports @workspace/db with DATABASE_URL unset and does not build a pool", () => {
    expect(process.env.DATABASE_URL).toBeUndefined();
    expect(isDbConfigured()).toBe(false);
    expect(poolCalls).toEqual([]);
    expect(() => {
      db.select();
    }).toThrow(DbUnavailableError);
    try {
      db.select();
    } catch (err) {
      expect(err).toBeInstanceOf(DbUnavailableError);
      expect(err).toMatchObject({ message: "database not configured" });
    }
  });

  it("GET /healthz returns 200 and db not-configured without connecting", async () => {
    expect(poolCalls).toEqual([]);
    const app = express();
    app.use(healthRouter);
    const { server, baseUrl } = await listen(app);
    servers.push(server);
    const response = await fetch(`${baseUrl}/healthz`);
    expect(response.status).toBe(200);
    expect(await response.json()).toEqual({ status: "ok", db: "not-configured" });
    expect(poolCalls).toEqual([]);
  });

  it("GET /api/inventions returns 503 when the database is not configured", async () => {
    const app = express();
    app.use(express.json());
    app.use(rejectWhenDatabaseNotConfigured);
    app.use("/api", inventionsRouter);
    const { server, baseUrl } = await listen(app);
    servers.push(server);
    const response = await fetch(`${baseUrl}/api/inventions`);
    expect(response.status).toBe(503);
    const body: unknown = await response.json();
    expect(body).toEqual({ error: "database not configured" });
    expect(JSON.stringify(body)).not.toContain("stack");
    expect(poolCalls).toEqual([]);
  });

  it("builds one drizzle instance from a mocked pool when a fake connection string is set", async () => {
    const previous = process.env.DATABASE_URL;
    poolCalls.length = 0;
    setPoolFactoryForTests(((connectionString: string) => new FakePgPool({ connectionString })) as unknown as NonNullable<
      Parameters<typeof setPoolFactoryForTests>[0]
    >);
    process.env.DATABASE_URL = FAKE_CONNECTION_STRING;
    try {
      expect(isDbConfigured()).toBe(true);
      const database = getDb();
      expect(database).toBe(getDb());
      expect(typeof database.select).toBe("function");
      expect(getPool()).toBe(getDb().$client);
      expect(poolCalls).toEqual([{ connectionString: FAKE_CONNECTION_STRING }]);
      expect(() => {
        db.select();
      }).not.toThrow();
      await getPool().end();
    } finally {
      setPoolFactoryForTests(null);
      if (previous === undefined) delete process.env.DATABASE_URL;
      else process.env.DATABASE_URL = previous;
    }
    expect(process.env.DATABASE_URL).toBeUndefined();
    expect(isDbConfigured()).toBe(false);
  });
});

#!/usr/bin/env node
import { spawn } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { isLoopbackPostgresUrl, samePostgresDatabase } from "./suite-policy.mjs";

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const packageManager = process.platform === "win32" ? "pnpm.cmd" : "pnpm";

function localTestValue(name) {
  if (process.env[name] !== undefined) return process.env[name];
  try {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const match = readFileSync(join(root, ".env.local"), "utf8").match(
      new RegExp(`^\\s*(?:export\\s+)?${escaped}\\s*=\\s*(.*)\\s*$`, "m"),
    );
    if (!match) return "";
    let value = match[1].trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    } else {
      value = value.replace(/\s+#.*$/, "");
    }
    return value;
  } catch (error) {
    if (error?.code === "ENOENT") return "";
    throw error;
  }
}

function runWorkspaceTest(label, selector, env, script = "test") {
  return new Promise((resolve) => {
    console.log(`\n[test] ${label}`);
    const child = spawn(
      packageManager,
      ["--filter", selector, "run", script],
      { cwd: root, env, stdio: "inherit" },
    );
    child.once("error", (error) => {
      console.error(`[test] ${label} could not start: ${error.message}`);
      resolve(1);
    });
    child.once("exit", (code, signal) => {
      resolve(code ?? (signal ? 1 : 0));
    });
  });
}

const isolatedEnv = { ...process.env };
delete isolatedEnv.DATABASE_URL;
delete isolatedEnv.FATHER_NATAL_CHART_JSON;
delete isolatedEnv.TESSERA_TEST_DATABASE_URL;
delete isolatedEnv.TESSERA_TEST_FATHER_NATAL_CHART_JSON;

let failures = 0;
for (const [label, selector] of [
  ["Suite safety policy", "@workspace/scripts"],
  ["Gitbook MCP", "@workspace/gitbook-mcp"],
  ["TESSERA v2", "@workspace/v2"],
  ["GitAI", "@workspace/gitai"],
]) {
  failures += await runWorkspaceTest(label, selector, { ...isolatedEnv });
}

const testDatabaseUrl = localTestValue("TESSERA_TEST_DATABASE_URL").trim();
if (!testDatabaseUrl) {
  console.log(
    "\n[test] Tessera API integration tests skipped. Set TESSERA_TEST_DATABASE_URL to a dedicated local test database (not DATABASE_URL).",
  );
} else {
  if (!isLoopbackPostgresUrl(testDatabaseUrl)) {
    console.error(
      "[test] Refusing an invalid or non-loopback PostgreSQL URL; use an explicit local test database.",
    );
    process.exit(2);
  }
  const appDatabaseUrl = localTestValue("DATABASE_URL").trim();
  if (appDatabaseUrl && samePostgresDatabase(testDatabaseUrl, appDatabaseUrl)) {
    console.error("[test] Refusing to run API tests against the same database target configured for the app.");
    process.exit(2);
  }
  const apiEnv = {
    ...isolatedEnv,
    DATABASE_URL: testDatabaseUrl,
    ...(localTestValue("TESSERA_TEST_FATHER_NATAL_CHART_JSON")
      ? { FATHER_NATAL_CHART_JSON: localTestValue("TESSERA_TEST_FATHER_NATAL_CHART_JSON") }
      : {}),
  };
  failures += await runWorkspaceTest("Tessera API (local test database)", "@workspace/api-server", apiEnv);
}

failures += await runWorkspaceTest(
  "Tessera learning memory",
  "@workspace/api-server",
  { ...isolatedEnv },
  "test:memory",
);

if (failures > 0) {
  console.error(`\n[test] ${failures} workspace test command(s) failed.`);
  process.exitCode = 1;
} else {
  console.log("\n[test] Workspace test run completed.");
}

import { drizzle } from "drizzle-orm/node-postgres";
import pg from "pg";
import * as schema from "./schema";

const { Pool } = pg;

export class DbUnavailableError extends Error {
  readonly code = "DB_NOT_CONFIGURED" as const;

  constructor() {
    super("database not configured");
    this.name = "DbUnavailableError";
  }
}

export function isDbConfigured(): boolean {
  return Boolean(process.env.DATABASE_URL);
}

type Database = ReturnType<typeof drizzle<typeof schema>>;
type PoolFactory = (connectionString: string) => pg.Pool;

const defaultPoolFactory: PoolFactory = (connectionString) => new Pool({ connectionString });
let poolFactory: PoolFactory = defaultPoolFactory;
let poolSingleton: pg.Pool | undefined;
let dbSingleton: Database | undefined;

/**
 * Test seam. Production boot never calls this.
 * Pass null to restore `pg.Pool` and drop any cached client.
 */
export function setPoolFactoryForTests(factory: PoolFactory | null): void {
  poolFactory = factory ?? defaultPoolFactory;
  poolSingleton = undefined;
  dbSingleton = undefined;
}

export function getPool(): pg.Pool {
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString) {
    throw new DbUnavailableError();
  }
  if (!poolSingleton) {
    poolSingleton = poolFactory(connectionString);
  }
  return poolSingleton;
}

export function getDb(): Database {
  if (!isDbConfigured()) {
    throw new DbUnavailableError();
  }
  if (!dbSingleton) {
    dbSingleton = drizzle(getPool(), { schema });
  }
  return dbSingleton;
}

function lazyProxy<T extends object>(resolve: () => T): T {
  return new Proxy({} as T, {
    get(_target, prop) {
      if (prop === "then") return undefined;
      const real = resolve();
      const value: unknown = Reflect.get(real, prop, real);
      if (typeof value === "function") {
        return (value as (...args: unknown[]) => unknown).bind(real);
      }
      return value;
    },
  });
}

const configuredAtLoad = isDbConfigured();

export const pool: pg.Pool = configuredAtLoad ? getPool() : lazyProxy(getPool);
export const db: Database = configuredAtLoad ? getDb() : lazyProxy(getDb);

export * from "./schema";

import assert from "node:assert/strict";
import test from "node:test";
import { execFileSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { MESHLOG } from "../src/brain/meshlog-labels.mjs";
import { isOldFallbackVector, localFallbackEmbedding, main } from "../scripts/reembed-fallback.mjs";

function repoRoot() {
  return execFileSync("git", ["rev-parse", "--show-toplevel"], { encoding: "utf8" }).trim();
}

function stripTypes(source) {
  return source
    .replace(/<[A-Za-z0-9_,\s[\]|&]+>/g, "")
    .replace(/:\s*[A-Za-z_][A-Za-z0-9_]*\[\]/g, "")
    .replace(/:\s*[A-Za-z_][A-Za-z0-9_]*/g, "");
}

// The pre-fix function, loaded from git rather than retyped. Parent of the commit
// that removed `(i % 32)` from neural-embeddings.ts.
function loadOldFallback(root) {
  const commit = execFileSync(
    "git",
    ["log", "-1", "--format=%H", "-S", "(i % 32)", "--", "artifacts/api-server/src/lib/neural-embeddings.ts"],
    { cwd: root, encoding: "utf8" },
  ).trim();
  assert.ok(commit, "git history has the pre-fix fallback");
  const src = execFileSync(
    "git",
    ["show", `${commit}^:artifacts/api-server/src/lib/neural-embeddings.ts`],
    { cwd: root, encoding: "utf8" },
  );
  const start = src.indexOf("const STOPWORDS");
  const end = src.indexOf("export async function generateEmbedding");
  assert.ok(start > 0 && end > start, "old fallback source is present");
  const chunk = src.slice(start, end);
  assert.match(chunk, /\(i % 32\)/);
  assert.doesNotMatch(chunk, /7919 \* block/);
  const factory = new Function(`${stripTypes(`const EMBEDDING_DIM = 256;\n${chunk}`)}\nreturn localFallbackEmbedding;`);
  return factory();
}

function cosine(a, b) {
  let dot = 0;
  let magA = 0;
  let magB = 0;
  const len = Math.min(a.length, b.length);
  for (let i = 0; i < len; i++) {
    dot += a[i] * b[i];
    magA += a[i] * a[i];
    magB += b[i] * b[i];
  }
  const denom = Math.sqrt(magA) * Math.sqrt(magB);
  return denom === 0 ? 0 : dot / denom;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function sampleWords(words, n, rand) {
  const bag = words.slice();
  const out = [];
  const take = Math.min(n, bag.length);
  for (let i = 0; i < take; i++) {
    const j = Math.floor(rand() * (bag.length - i)) + i;
    const swap = bag[i];
    bag[i] = bag[j];
    bag[j] = swap;
    out.push(bag[i]);
  }
  return out;

import type { ErrorRequestHandler, Request, RequestHandler, Response } from "express";
import { DbUnavailableError } from "@workspace/db";

export const DATABASE_NOT_CONFIGURED_BODY = {
  error: "database not configured",
} as const;

function fullPath(req: Request): string {
  const raw = req.originalUrl || req.url || req.path;
  const path = raw.split("?")[0] ?? "";
  return path.length > 0 ? path : "/";
}

function isDatabaseOptionalPath(path: string): boolean {
  if (path === "/healthz" || path === "/api/healthz") return true;
  if (path === "/api/admin/session" || path.startsWith("/api/admin/session/")) return true;
  if (path === "/api/admin/surface" || path.startsWith("/api/admin/surface/")) return true;
  return false;
}

export function isDbUnavailableError(err: unknown): boolean {
  if (err instanceof DbUnavailableError) return true;
  return err instanceof Error && err.name === "DbUnavailableError";
}

export const rejectWhenDatabaseNotConfigured: RequestHandler = (req, res, next) => {
  if (process.env.DATABASE_URL) {
    next();
    return;
  }
  const path = fullPath(req);
  if (!path.startsWith("/api") || isDatabaseOptionalPath(path)) {
    next();
    return;
  }
  res.status(503).json(DATABASE_NOT_CONFIGURED_BODY);
};

function isUnavailableBody(body: unknown): boolean {
  if (!body || typeof body !== "object") return false;
  const error = (body as { error?: unknown }).error;
  return error === DATABASE_NOT_CONFIGURED_BODY.error;
}

export function rewriteDatabaseUnavailableJson(res: Response): void {
  if (process.env.DATABASE_URL) return;
  const originalJson = res.json.bind(res);
  res.json = ((body?: unknown) => {
    if (res.statusCode >= 500 && isUnavailableBody(body)) {
      res.status(503);
      return originalJson(DATABASE_NOT_CONFIGURED_BODY);
    }
    return originalJson(body);
  }) as Response["json"];
}

export const dbUnavailableErrorHandler: ErrorRequestHandler = (err, _req, res, next) => {
  if (res.headersSent) {
    next(err);
    return;
  }
  if (isDbUnavailableError(err)) {
    res.status(503).json(DATABASE_NOT_CONFIGURED_BODY);
    return;
  }
  next(err);
};

import { Router, type IRouter } from "express";
import { HealthCheckResponse } from "@workspace/api-zod";

const router: IRouter = Router();

router.get("/healthz", (_req, res) => {
